const weather = $input.first().json;

// Current weather
const current = weather.current;

// Today's forecast
const today = current.time.split("T")[0];
const dailyIndex = weather.daily.time.indexOf(today);

// Calculate today's maximum rain probability
const todayHourlyIndexes = weather.hourly.time
  .map((time, index) => time.startsWith(today) ? index : -1)
  .filter(index => index !== -1);

const rainProbabilities = todayHourlyIndexes
  .map(index => weather.hourly.precipitation_probability[index])
  .filter(value => value !== null && value !== undefined);

const maxRainChance = rainProbabilities.length
  ? Math.max(...rainProbabilities)
  : null;

return [
  {
    json: {
      location: "Al-Nasr, Gaza",
      date: today,
      timezone: weather.timezone,

      currentWeather: {
        temperature: current.temperature_2m,
        feelsLike: current.apparent_temperature,
        humidity: current.relative_humidity_2m,
        windSpeed: current.wind_speed_10m,
        precipitation: current.precipitation,
        observationTime: current.time
      },

      todayForecast: {
        maxTemperature: weather.daily.temperature_2m_max[dailyIndex],
        minTemperature: weather.daily.temperature_2m_min[dailyIndex],
        rainProbability: maxRainChance,
        sunrise: weather.daily.sunrise[dailyIndex],
        sunset: weather.daily.sunset[dailyIndex]
      },

      units: {
        temperature: "°C",
        humidity: "%",
        windSpeed: "km/h",
        precipitation: "mm",
        rainProbability: "%"
      }
    }
  }
];
